9	  const data = UpdateSchema.parse(input);
10	  const supabase = await createClient();
11	  // RLS scopes this to the owner's rows; a foreign id simply matches 0 rows.
12	  const { error } = await supabase
13	    .from("items")
14	    .update({
15	      name: data.name,
16	      brand: data.brand,
17	      category: data.category,
18	      subcategory: data.subcategory,
19	      colors: data.colors,
20	      pattern: data.pattern,
21	      material: data.material,
22	      texture: data.texture,
23	      price: data.price,
24	      formality: data.formality,
25	      seasons: data.seasons,
26	    })
27	    .eq("id", itemId);
28	  if (error) throw error;
29	  revalidatePath("/closet");
30	  revalidatePath(`/closet/${itemId}`);
31	}
32	
33	export async function archiveItem(itemId: string) {
34	  const supabase = await createClient();
35	  const { error } = await supabase
36	    .from("items")
37	    .update({ archived: true })
38	    .eq("id", itemId);
39	  if (error) throw error;
40	  revalidatePath("/closet");
41	  redirect("/closet");
42	}
