"use client";

import { useState, useTransition } from "react";
import { archiveItem } from "@/app/closet/[itemId]/actions";
import type { Tags } from "@/lib/ai/tagging-schema";

import { ItemView, type GoesWithCard } from "./item-view";
import { ItemEditSheet } from "./item-edit-sheet";

export type DetailItem = {
  id: string;
  name: string | null;
  brand: string | null;
  category: Tags["category"];
  subcategory: string | null;
  colors: string[];
  material: string | null;
  texture: string | null;
  pattern: string | null;
  price: number | null;
  formality: number | null;
  seasons: string[];
};

/**
 * The item detail shell.
 *
 * This file used to BE the tag form. The design's item detail is read-first —
 * cutouts are the hero, the stat tiles answer "how do I actually wear this?",
 * and editing sits behind `⋯`. So this component now owns only the switch
 * between the two: `ItemView` reads, `ItemEditSheet` writes.
 */
export function ItemDetail({
  item,
  imageUrl,
  brandSuggestions,
  stats,
  goesWith,
  styleCta,
}: {
  item: DetailItem;
  imageUrl: string;
  brandSuggestions: string[];
  stats: { wears: number; costPerWear: string | null; lastWorn: string };
  goesWith: GoesWithCard[];
  styleCta?: React.ReactNode;
}) {
  const [editing, setEditing] = useState(false);
  const [, start] = useTransition();

  function archive() {
    if (!confirm("Remove this piece from your closet?")) return;
    start(async () => {
      await archiveItem(item.id);
    });
  }

  return (
    <>
      <ItemView
        item={item}
        imageUrl={imageUrl}
        stats={stats}
        goesWith={goesWith}
        onEdit={() => setEditing(true)}
        onArchive={archive}
        styleCta={styleCta}
      />
      {editing && (
        <ItemEditSheet
          item={item}
          brandSuggestions={brandSuggestions}
          onClose={() => setEditing(false)}
        />
      )}
    </>
  );
}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { Archive } from "lucide-react";
import { Kicker } from "@/components/ui-fitcheck/kicker";
import { FORMALITY_LABEL } from "@/lib/closet/vocab";
import type { DetailItem } from "./item-detail";

export type GoesWithCard = { id: string; name: string; imageUrl: string };

/** A stat tile. `value` is already formatted — this renders, it does not compute. */
function Tile({ value, label, serifSize }: { value: string; label: string; serifSize: string }) {
  return (
    <div className="flex-1 rounded-[13px] bg-surface-1 p-[14px] shadow-[inset_0_0_0_1px_var(--hairline-2)]">
      <div className={`font-serif ${serifSize} leading-none text-foreground`}>{value}</div>
      <div className="mt-[6px] text-[10px] uppercase tracking-[0.1em] text-muted-dim">{label}</div>
    </div>
  );
}

function TagRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between px-4 py-[14px] not-last:border-b not-last:border-[var(--hairline-2)]">
      <div className="text-[13px] text-muted-dim">{label}</div>
      <div className="text-right text-[14px] text-value">{value}</div>
    </div>
  );
}

/**
 * Item detail, read-first (Fitcheck.dc.html:587-657).
 *
 * The screen the design calls the canonical one: cutout is the hero, everything
 * else is quiet around it, and the rust accent appears EXACTLY once — the
 * formality meter. Editing lives behind `⋯`; this screen answers "how do I
 * actually wear this?", not "what are its tags?".
 *
 * It opens with a full-bleed stage, so it deliberately does NOT use
 * `.screen-top` — the two floating controls carry the safe-area inset instead.
 */
export function ItemView({
  item,
  imageUrl,
  stats,
  goesWith,
  onEdit,
  onArchive,
  styleCta,
}: {
  item: DetailItem;
  imageUrl: string;
  stats: { wears: number; costPerWear: string | null; lastWorn: string };
  goesWith: GoesWithCard[];
  onEdit: () => void;
  onArchive: () => void;
  /** The primary action. Supplied by the shell so this stays presentational. */
  styleCta?: React.ReactNode;
}) {
  const router = useRouter();
  const title = item.name ?? item.subcategory ?? item.category;
  const subtitle = [item.subcategory, item.colors[0]].filter(Boolean).join(" · ");

  const tags: [string, string | null][] = [
    ["Category", item.category],
    ["Colour", item.colors.join(" · ") || null],
    ["Material", item.material],
    ["Texture", item.texture],
    ["Pattern", item.pattern],
    ["Seasons", item.seasons.join(" · ") || null],
  ];

  return (
    <div className="flex min-h-dvh flex-1 flex-col">
      <div className="absolute inset-x-[18px] top-[calc(env(safe-area-inset-top)+18px)] z-40 flex justify-between">
        <button
          type="button"
          onClick={() => {
            // Dead on a shared link, a refresh or a PWA cold start otherwise —
            // the same trap the outfit detail's back button hit.
            if (window.history.length > 1) router.back();
            else router.push("/closet");
          }}
          aria-label="Back"
          className="grid size-10 place-items-center rounded-full bg-[rgba(20,19,22,0.7)] text-xl text-foreground shadow-[inset_0_0_0_1px_var(--hairline-7)] backdrop-blur-[10px]"
        >
          ‹
        </button>
        <button
          type="button"
          onClick={onEdit}
          aria-label="More"
          className="grid size-10 place-items-center rounded-full bg-[rgba(20,19,22,0.7)] text-lg text-muted-foreground shadow-[inset_0_0_0_1px_var(--hairline-7)] backdrop-blur-[10px]"
        >
          ⋯
        </button>
      </div>

      <div className="flex-1 overflow-y-auto pb-[130px]">
        <div className="surface-stage relative h-[360px]">
          {imageUrl && (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={imageUrl}
              alt={title}
              className="absolute inset-0 size-full object-contain p-10"
            />
          )}
        </div>

        <div className="px-6 pt-[6px]">
          {item.brand && <Kicker>{item.brand}</Kicker>}
          <h1 className="mt-[6px] font-serif text-[30px]/[1.05] text-foreground">{title}</h1>
          {subtitle && <p className="mt-[5px] text-sm text-muted-foreground">{subtitle}</p>}

          <div className="mt-[22px] flex gap-[10px]">
            <Tile value={String(stats.wears)} label="Times worn" serifSize="text-[26px]" />
            {/* Omitted rather than shown as £0.00 — an unpriced item has no
                cost per wear, and printing one states something false. */}
            {stats.costPerWear && (
              <Tile value={stats.costPerWear} label="Cost / wear" serifSize="text-[26px]" />
            )}
            <Tile value={stats.lastWorn} label="Last worn" serifSize="text-[17px]" />
          </div>

          {/* The One Rust Rule's single spend on this screen. Always paired with
              the WORD — a bare 1–5 means nothing to the person reading it. */}
          <div className="mt-[22px]">
            <div className="mb-[10px] flex justify-between">
              <Kicker>Formality</Kicker>
              <span className="text-xs text-muted-foreground">
                {FORMALITY_LABEL[item.formality ?? 3]}
              </span>
            </div>
            <div className="flex gap-[6px]">
              {[1, 2, 3, 4, 5].map((n) => (
                <div
                  key={n}
                  className={`h-2 flex-1 rounded-full ${
                    n <= (item.formality ?? 3) ? "bg-brand" : "bg-foreground/10"
                  }`}
                />
              ))}
            </div>
          </div>

          <div className="mt-[22px] overflow-hidden rounded-[14px] bg-surface-1 shadow-[inset_0_0_0_1px_var(--hairline-2)]">
            {tags
              .filter((t): t is [string, string] => Boolean(t[1]))
              .map(([k, v]) => (
                <TagRow key={k} label={k} value={v} />
              ))}
          </div>

          {goesWith.length > 0 && (
            <>
              <Kicker className="mb-3 mt-[26px] block">Goes with</Kicker>
              <div className="flex gap-[10px] overflow-x-auto">
                {goesWith.map((g) => (
                  <Link key={g.id} href={`/closet/${g.id}`} className="w-[92px] shrink-0">
                    <div className="relative aspect-square rounded-[12px] bg-surface-2 shadow-[inset_0_0_0_1px_var(--hairline-2)]">
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      <img
                        src={g.imageUrl}
                        alt=""
                        className="absolute inset-0 size-full object-contain p-3"
                      />
                    </div>
                    <div className="mt-[6px] text-center text-[10.5px]/[1.2] text-muted-foreground">
                      {g.name}
                    </div>
                  </Link>
                ))}
              </div>
            </>
          )}
        </div>
      </div>

      <div className="sticky bottom-0 z-30 flex gap-3 bg-gradient-to-t from-canvas from-60% to-transparent px-[22px] pb-[calc(env(safe-area-inset-bottom)+14px)] pt-[14px]">
        <button
          type="button"
          onClick={onArchive}
          aria-label="Archive"
          className="grid h-[54px] w-14 place-items-center rounded-[14px] bg-surface-2 text-muted-foreground shadow-[inset_0_0_0_1px_var(--hairline-6)]"
        >
          <Archive size={19} />
        </button>
        {styleCta}
      </div>
    </div>
  );
}

/**
 * The three tiles at the top of item detail (Fitcheck.dc.html:609-627).
 *
 * The wear rows behind this come from `wear_logs` joined through `outfit_items`
 * — a wear is logged against an OUTFIT, so an item's wear count is "how many
 * logged outfits contained it".
 */

/**
 * Euro, formatted for the English UI — "€50.00", not "50,00 €".
 *
 * `en-IE` is the euro locale whose conventions match the rest of the interface;
 * the German content the spec plans will want `de-DE` here. One hard-coded
 * currency beats a fake one until Settings owns the choice.
 */
const MONEY = new Intl.NumberFormat("en-IE", { style: "currency", currency: "EUR" });

/**
 * Whole calendar days between two `YYYY-MM-DD` keys.
 *
 * Built from the date parts via `Date.UTC` rather than parsing the strings as
 * local timestamps: `worn_on` is a DATE in the user's local calendar, and
 * subtracting two local timestamps across a DST change yields 23 or 25 hours,
 * which rounds to the wrong number of days.
 */
function daysBetween(from: string, to: string): number {
  const a = Date.UTC(+from.slice(0, 4), +from.slice(5, 7) - 1, +from.slice(8, 10));
  const b = Date.UTC(+to.slice(0, 4), +to.slice(5, 7) - 1, +to.slice(8, 10));
  return Math.round((b - a) / 86_400_000);
}

/**
 * Cost-per-wear is null rather than 0 or "—" when there is no price or no
 * wears: dividing by zero wears would print £Infinity, and showing £0.00 for an
 * unpriced item states something false. The UI hides the tile instead.
 */
export function itemWearStats(
  logs: { worn_on: string }[],
  price: number | null,
  today: string,
): { wears: number; costPerWear: string | null; lastWorn: string } {
  const wears = logs.length;
  const costPerWear = price != null && wears > 0 ? MONEY.format(price / wears) : null;

  if (!wears) return { wears, costPerWear, lastWorn: "Never" };

  const latest = logs.reduce((a, b) => (a.worn_on > b.worn_on ? a : b)).worn_on;
  const d = daysBetween(latest, today);
  // `d <= 0` also covers a log dated ahead of today — possible if the device
  // clock or timezone moved. "Today" is the honest reading; a negative count
  // would not be.
  const lastWorn = d <= 0 ? "Today" : d === 1 ? "Yesterday" : `${d} days ago`;
  return { wears, costPerWear, lastWorn };
}

